entries[89701] = { ["name"] = "Jadenatter mit Rubinaugen", ["text"] = "Wirken in 2 sek. 5\nDiese winzige Figurine könnte eine Abbildung des Hohepriesters Venoxis sein, auch wenn Schlangen in der gesamten Trollkultur verehrt werden. Die fein gearbeiteten Kiefer der Figur können geöffnet und geschlossen werden, möglicherweise um einen Finger zum Bluten zu bringen.\nJadenatter mit Rubinaugen\nWird beim Aufheben gebunden" }
