entries[89890] = { ["name"] = "Unheimlicher Gluthauergötze", ["text"] = "Wirken in 2 sek. 5\nAls die Hochelfen in den Krieg gegen die Amanitrolle zogen, konnten die Elfen nicht verstehen, wie die Waffenverzauberungen der Trolle mächtiger als ihre eigenen sein konnten. Daraufhin stahlen die Elfen das uralte Wissen der Trollzauberer, einschließlich dem des berühmten Zanza, und nutzten Idole wie dieses hier, um ihre eigenen Versionen der Trollverzauberungen zu erschaffen.\nUnheimlicher Gluthauergötze\nWird beim Aufheben gebunden" }
entries[89891] = { ["name"] = "Cinnabaritschmuckstück", ["text"] = "Wirken in 2 sek. 5\nDieses Kleinod wurde aus einem roten Mineral vulkanischen Ursprungs hergestellt, das nebenbei sehr giftig ist. Die Inschrift auf der Rückseite besagt, dass es einst Eigentum von Min'loth der Schlange war. Spuren von Seepocken deuten darauf hin, dass das Schmuckstück einige Zeit unter Wasser verbracht hat.\nCinnabaritschmuckstück\nWird beim Aufheben gebunden" }
entries[89892] = { ["name"] = "Bombe werfen", ["text"] = "15 Meter Reichweite\nSofort\nWirft eine Bombe auf einen nahen Ölspritzer, um ihn anzuzünden." }
entries[89893] = { ["name"] = "Münze aus Eldre'Thalas", ["text"] = "Wirken in 2 sek. 5\nEinstmals war dieser Ort eine Hauptstadt der Hochgeborenen, die Stadt von Königin Azsharas Arkanisten. Nach der Großen Zerschlagung fiel sie jedoch dem Verfall und letztendlich dem Vergessen anheim. Die Ruine ist nunmehr als der Düsterbruch bekannt.\nMünze aus Eldre'Thalas\nWird beim Aufheben gebunden" }
entries[89894] = { ["name"] = "Zerschmetterte Gleve", ["text"] = "Wirken in 2 sek. 5\nDas ist das Fragment eines großen, mit drei Klingen versehenen Projektiltyps, der von elfischen Belagerungswaffen verschossen wird. Wenn Glevenwerfer auch heute noch in Gebrauch sind, so ist dieses Fragment doch eindeutig altertümlich und äußerst reich verziert, selbst für nachtelfische Verhältnisse.\nZerschmetterte Gleve\nWird beim Aufheben gebunden" }
entries[89895] = { ["name"] = "Spiralförmige Ammonitenschale", ["text"] = "Wirken in 2 sek. 5\nAmmoniten sind eine ausgestorbene Kopffüßlerart, die verschiedenartig gewundene Schalen besaß. Dies ist ein Fossil eines kleinen Exemplars, sie konnten jedoch recht groß werden.\nSpiralförmige Ammonitenschale\nWird beim Aufheben gebunden" }
entries[89896] = { ["name"] = "Gründrachenring", ["text"] = "Wirken in 2 sek. 5\nDas ist vermutlich eine künstlerische Darstellung von Eranikus, Gemahl von Ysera. Eranikus fiel der Verderbnis des Smaragdgrünen Alptraums anheim und wurde später erlöst. In die Innenseite sind die Worte 'Andu-falah-dor!' graviert.\nGründrachenring\nWird beim Aufheben gebunden" }
