entries[90410] = { ["name"] = "Gekerbtes Schwert von Tunadil dem Erlöser", ["text"] = "Wirken in 2 sek. 5\nDie Klinge zerbrach, als der Paladin im Kampf gegen den Schreckenswyrm Kaldrigos auf sie stürzte.\nGekerbtes Schwert von Tunadil dem Erlöser\nWird beim Aufheben gebunden" }
entries[90411] = { ["name"] = "Üppiger Türklopfer", ["text"] = "Wirken in 2 sek. 5\nIhr könnt nur spekulieren, welche Art Wohnhaus oder Geschäft dieses Artefakt einst zierte. Dieser, äh... dralle Türklopfer hat die Form einer vollbusigen Zwergin, die mit breitem Lächeln mehrere Bierhumpen vor sich herträgt. Das Lächeln hat eindeutig eine Zahnlücke.\nÜppiger Türklopfer\nWird beim Aufheben gebunden" }
entries[90412] = { ["name"] = "Stiefelabsatz mit Ornamenten", ["text"] = "Wirken in 2 sek. 5\nDie Aufmerksamkeit, die diesem einzelnen Absatz geschenkt wurde, lässt darauf schließen, dass der gesamte Stiefel einst magische Qualitäten aufwies. Die Ornamente sind größtenteils abstrakt, Ihr könnt jedoch kleine Waldtiere ausmachen - Eichhörnchen, Rehe, vielleicht ein Stinktier - die in dem verschnörkelten Muster versteckt sind.\nStiefelabsatz mit Ornamenten\nWird beim Aufheben gebunden" }
entries[90413] = { ["name"] = "Goldener Nachttopf", ["text"] = "Wirken in 2 sek. 5\nAnscheinend erledigen die Reichen und Mächtigen all ihre Geschäfte mit Stil. Dieses gute Stück ist mit Fischen verziert, die aus stilisiertem Wasser springen.\nGoldener Nachttopf\nWird beim Aufheben gebunden" }
entries[90414] = { ["name"] = "Despawn All Summons" }
entries[90415] = { ["name"] = "Flügelhelm von Kernhammer", ["text"] = "Wirken in 2 sek. 5\nDer Größe seines Helms nach zu urteilen, war der Dunkeleisenthan Kernhammer einfach nur gewaltig. Oder gewaltig fett.\nFlügelhelm von Kernhammer\nWird beim Aufheben gebunden" }
entries[90416] = { ["name"] = "Alle Passagiere absetzen" }
entries[90417] = { ["name"] = "Kornvorrat vergiften", ["text"] = "5 Meter Reichweite\nWirken in 1 sek.\nVergiftet die Getreidevorräte in den Schwarzfelstiefen." }
entries[90418] = { ["name"] = "Volcanic Skybox" }
entries[90419] = { ["name"] = "Eisensterns versteinerter Schild", ["text"] = "Wirken in 2 sek. 5\nDer Legende nach schnitzte der Dunkeleisenthan Eisenstern diesen Schild aus dem Holz eines heiligen Baumes der Hochelfen und verzauberte ihn, auf dass er so hart wie Stein werde.\nEisensterns versteinerter Schild\nWird beim Aufheben gebunden" }
entries[90420] = { ["name"] = "Schädelförmiger Blumentopf", ["text"] = "Wirken in 2 sek. 5\nWaldtrolle haben eine starke Affinität zur umgebenden Flora. Die Körper der Trolle selbst können Heimat simpler Pflanzenkulturen sein, zum Beispiel von Moosen oder Algen, was ihnen ihre charakteristische grüne Farbschattierung verleiht.\nSchädelförmiger Blumentopf\nWird beim Aufheben gebunden" }
entries[90421] = { ["name"] = "Jadearmband mit Münzen", ["text"] = "Wirken in 2 sek. 5\nDieses Armband besteht aus einem Silberkettchen, an dem polierte Jadesteine und trollische Münzen befestigt sind. Da Trolle eher Gold als Schmuckmaterial bevorzugen, ist es möglich, dass das Silber von einem anderen Volk erbeutet wurde - was wiederum bedeutet, dass dieser Fund jüngeren Ursprungs ist. Die Münzen sind ungewöhnlich, auf jeder ist das Gesicht einer anderen Trollfrau dargestellt.\nJadearmband mit Münzen\nWird beim Aufheben gebunden" }
entries[90422] = { ["name"] = "Kolossales Spalten" }
entries[90423] = { ["name"] = "Figur von Gahz'rilla", ["text"] = "Wirken in 2 sek. 5\nDie Sandtrolle beschworen diese gewaltige weiße Hydra aus einem heiligen Wasserbecken in Zul'Farrak und verehrten sie daraufhin als Gottheit. Gahz'rillas Schuppen sind elektrisch aufgeladen und selbst diese kleine Figur knistert vor Energie. Innerhalb von Zul'Farrak ist die legendäre Hydra ein häufig auftretendes architektonisches und ornamentales Motiv.\nFigur von Gahz'rilla\nWird beim Aufheben gebunden" }
entries[90424] = { ["name"] = "Glubtok Transition Invisibility" }
entries[90425] = { ["name"] = "Feuerregen", ["text"] = "Unbegrenzte Reichweite\nSofort\nFügt Gegnern im Effektbereich Feuerschaden zu." }
entries[90426] = { ["name"] = "Feuerregen", ["text"] = "Unbegrenzte Reichweite\nSofort\nSchießt einen Feuerball in den Schmelztiegel des Gemetzels." }
