entries[90451] = { ["name"] = "Amphore der Kaldorei", ["text"] = "Wirken in 2 sek. 5\nDieser schlanke Krug mit den ovalen Henkeln wurde zum Mischen oder Aufbewahren darnassischen Weins genutzt. Selbst nach all dieser Zeit steigt Euch von den angetrockneten Resten im Inneren noch ein leichter Ingwerduft entgegen.\nAmphore der Kaldorei\nWird beim Aufheben gebunden" }
entries[90452] = { ["name"] = "Uraltes Haifischgebiss", ["text"] = "Wirken in 2 sek. 5\nHaie verfügen über keine echten Knochen, lediglich Knorpel. Da ein großer Teil ihrer Jagdmethode darauf beruht, wirklich fest zuzubeissen, sind verlorene Zähne ein gewöhnliches Resultat. Daher besitzen Haie mehrere Zahnreihen, die solang sie leben ständig ersetzt werden.\nUraltes Haifischgebiss\nWird beim Aufheben gebunden" }
entries[90453] = { ["name"] = "Malachitbesetzte Silberhaarnadel", ["text"] = "Wirken in 2 sek. 5\nUnter die Einfassung des Edelsteins sind die folgenden Worte graviert: \"Für Theleste, zu ihrem vierundzwanzigsten Geburtsjahre.\"\nMalachitbesetzte Silberhaarnadel\nWird beim Aufheben gebunden" }
