entries[90473] = { ["name"] = "Item - Rogue T11 4P Bonus", ["text"] = "Jeder Eurer automatischen Nahkampfangriffe hat eine Chance von 1%, 15 Sek. lang den Effekt 'Tödliche Absichten' zu gewähren, welcher die kritische Trefferchance Eures nächsten Wirkens von 'Vergiften' oder 'Ausweiden' um 100% erhöht.\n(Procchance: 1%)" }
