entries[90504] = { ["name"] = "Der verbeulte Schild des Horuz Krähentod", ["text"] = "Wirken in 2 sek. 5\nAls Horuz und seine Gefährten den Schreckenswyrm Kaldrigos bekämpften, beging der sagenumwobene Held einen tödlichen Fehler. Er stand direkt hinter dem Drachen. Tut das nie.\nDer verbeulte Schild des Horuz Krähentod\nWird beim Aufheben gebunden" }
entries[90505] = { ["name"] = "Item - Shaman T11 Elemental 4P Bonus", ["text"] = "Verringert die Zauberzeit Eures Zaubers 'Blitzschlag' um 10%." }
entries[90506] = { ["name"] = "Versengter Stab von Schattenpriester Anund", ["text"] = "Wirken in 2 sek. 5\nDieser Holzstab wurde von einem Arkanodem vollständig verkohlt. Seinen Besitzer ereilte das gleiche Schicksal.\nVersengter Stab von Schattenpriester Anund\nWird beim Aufheben gebunden" }
entries[90507] = { ["name"] = "Todesser", ["text"] = "Sofort\nJedes Mal, wenn Ihr eine Todesrune erhaltet, erhaltet ihr ebenfalls 30 Sek. lang eine Steigerung der Angriffskraft um 1%. Bis zu 3-mal stapelbar." }
entries[90508] = { ["name"] = "Burning Steppes Guardian Aura (H)" }
entries[90509] = { ["name"] = "Szepter von Charlga Klingenflanke", ["text"] = "Wirken in 2 sek. 5\nAuch wenn diese Artefaktfragmente mit zwergischen vermischt waren, ist dieses Szepter eindeutig nicht von Zwergenhand, sondern von Stachelebern gefertigt. In der Tat wurde es einst von Charlga Klingenflanke selbst geführt. Möglicherweise kam es in den Besitz von Zwergen, als Helden versuchten, den Kral der Klingenhauer einzunehmen.\nSzepter von Charlga Klingenflanke\nWird beim Aufheben gebunden" }
entries[90510] = { ["name"] = "Quest Invisibility 25" }
entries[90511] = { ["name"] = "Invisibility Detection Quest 25" }
entries[90518] = { ["name"] = "Mithrilkette von Zornesschmied", ["text"] = "Wirken in 2 sek. 5\nDie Familienlinie der Zornesschmied durchzieht die gesamte Geschichte der Dunkeleisenzwerge. Das ist eine Kette, die von Than Zornesschmied getragen wurde, dem Vorfahren von General Zornesschmied, der noch immer die Armeen des Dunkeleisenklans im Schwarzfels befehligt.\nMithrilkette von Zornesschmied\nWird beim Aufheben gebunden" }
entries[90519] = { ["name"] = "Schädelstab von Schattenschmiede", ["text"] = "Wirken in 2 sek. 5\nDie Familie Schattenschmiede hinterließ einen Schandfleck auf der Geschichte der Dunkeleisenzwerge. Eisenthan Schattenschmiede war allen Berichten zufolge ein grausamer Despot, der viele seiner eigenen Untertanen folterte und tötete. Allgemein wird angenommen, er sei ein Hexenmeister gewesen, dennoch halten sich hartnäckige Gerüchte, dass er einer der ersten zwergischen Schamanen war.\nSchädelstab von Schattenschmiede\nWird beim Aufheben gebunden" }
entries[90520] = { ["name"] = "Arkane Überladung" }
entries[90521] = { ["name"] = "Aufziehgnom", ["text"] = "Wirken in 2 sek. 15\nMechagnome wurden von den Titanen erschaffen und sie fungierten, ähnlich wie die Irdenen, als Diener und Hüter. Dieser Mechagnom wurde vermutlich beschädigt, denn statt seiner ursprüngliche Aufgabe nachzugehen scheint er ganz damit zufrieden zu sein, Euch einfach nur nachzulaufen.\nAufziehgnom\nWird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euren Aufziehgnom beschwören oder wieder freigeben." }
entries[90522] = { ["name"] = "Wasserhülle", ["text"] = "40 Meter Reichweite\nWirken in 2 sek.\nAbsorbiert 50000 Schaden. Wenn die Wasserhülle bricht, explodiert sie und fügt Feinden in einem Umkreis von 8 Metern 48750 bis 51250 Frostschaden zu." }
entries[90523] = { ["name"] = "Aufziehgnom", ["text"] = "Sofort\nMit Rechtsklick Euren Aufziehgnom beschwören oder wieder freigeben." }
entries[90524] = { ["name"] = "Wasserexplosion", ["text"] = "40 Meter Reichweite\nSofort\nVerursacht an allein Feinden im Umkreis von 8 Metern 48750 bis 51250 Frostschaden." }
entries[90528] = { ["name"] = "See Quest Invis 5" }
entries[90546] = { ["name"] = "Trampelschutz", ["text"] = "Sofort\nVom mächtigen Olaf beschützt. Helix kann nicht sterben, solange sein Trampel ihn beschützt." }
entries[90550] = { ["name"] = "Arkanbeschuss", ["text"] = "100 Mana 30 Meter Reichweite\nWirken in 2 sek.\nSchleudert mehrere Geschosse auf das feindliche Ziel und verursacht Arkanschaden." }
entries[90551] = { ["name"] = "Überwältigende Kraft", ["text"] = "100 Meter Reichweite\nWirken in 5 sek.\nSendet einen Magiebogen aus, der bei dem ausgewählten Feind Arkanschaden verursacht." }
entries[90553] = { ["name"] = "Kelch der Bergkönige", ["text"] = "Wirken in 2 sek. 15\nZusätzlich zum dichten Edelsteinzierrat ist dieser Kelch über und über mit Runen bedeckt, welche die Thronfolgezeremonie eines Zwergenkönigs rühmen. Obwohl es sicherlich Teil dieser Zeremonie war, aus diesem Kelch zu trinken, beschreiben die Runen dennoch einen \"Schwerttanz\", der von Zwergenkriegerinnen dargeboten wurde. Diese Aufführung - teils Ritual, teils Schaukampf - entwickelte sich aus blutigen Duellen, die einst in weniger kultivierten Zeitaltern der zwergischen Geschichte stattfanden.\nKelch der Bergkönige\nWird beim Aufheben gebunden\nSpielzeug\nBenutzen: Werdet Zeuge eines historischen Schwerttanzes. (10 Min Abklingzeit)" }
