entries[90608] = { ["name"] = "Zin'rokh der Weltenzerstörer", ["text"] = "Wirken in 2 sek. 15\nEuren Nachforschungen zufolge war diese Waffe einer der vielen Schätze von Hakkar, dem Seelenschinder, in Zul'Gurub. Hakkar wurde jedoch vor Jahren bezwungen und dieses Schwert unter vielen mächtigen Kriegern und Paladinen weitergereicht, bevor es schließlich brach. Es ist erstaunlich, dass Ihr in der Lage wart, es zu rekonstruieren aber auch ein wenig beunruhigend: wenn der Weltenzerstörer zurückkehrt, ist der Seelenschinder vielleicht nicht weit.\nZin'rokh der Weltenzerstörer\nAccountgebunden\nEinzigartigZweihändig Schwert\n3,789 - 5,685 Schaden Tempo 3.80\n(1,247 Schaden pro Sekunde)\n+341 Stärke\n+512 Ausdauer\nErhöht Eure Trefferwertung um + 216.\nErhöht Eure kritische Trefferwertung um + 238.\nHaltbarkeit 120 / 120\n85" }
entries[90609] = { ["name"] = "Kette aus kleinen rosa Perlen", ["text"] = "Wirken in 2 sek. 5\nFür sich allein gesehen, sind die Perlen nicht besonders groß. Es ist jedoch bemerkenswert, dass alle zweiundvierzig so gut wie identisch zu sein scheinen. Statt dem Weiß oder dem seltenen Schwarz gewöhnlicher Austernperlen, sind diese hier von einer zarten rosigen Farbe. Eine Pilgermuschelschale als Anhänger rundet das Schmuckstück ab.\nKette aus kleinen rosa Perlen\nWird beim Aufheben gebunden" }
entries[90610] = { ["name"] = "Kästchen mit winzigen Glastierchen", ["text"] = "Wirken in 2 sek. 5\nErstaunlicherweise ist es Euch gelungen, eine ganze Menagerie dieser elfischen Glastierchen in ihrer ursprünglichen Aufbewahrungstruhe zu finden. Während einige der Figuren natürlich Sprünge und Risse aufweisen, wurde der Kopf des Hirsches ganz eindeutig mit Absicht abgebrochen. Die Initiale 'T' ist in den Boden der Truhe geschnitzt.\nKästchen mit winzigen Glastierchen\nWird beim Aufheben gebunden" }
entries[90611] = { ["name"] = "Gesprungene Kristallphiole", ["text"] = "Wirken in 2 sek. 5\nEine Notiz auf festem Pergament ist an die Flasche gebunden. 'Liebster P., nun da ich weiß, dass wir nie zusammenkommen können, ist es mein Wunsch, diesen Trank aus Spinnengift zu trinken. Solltest Du diese Notiz finden, hoffe ich, dass Du dasselbe tust. Möge Elune über unsere Seelen wachen.'\nGesprungene Kristallphiole\nWird beim Aufheben gebunden" }
entries[90612] = { ["name"] = "Szepter von Xavius", ["text"] = "Wirken in 2 sek. 5\nXavius war für viele der Greuel verantwortlich, welche die Nachtelfen während des Krieges der Ahnen erleiden mussten. Malfurion Sturmgrimm gelang es schließlich, Xavius' Pläne zu vereiteln, was letztendlich zu dessen Tod führte. Daraufhin folterte Sargeras Xavius' Seele für eine Weile, bis er ihn schließlich mit der verderbten Gestalt des ersten Satyrs 'segnete'.\nSzepter von Xavius\nWird beim Aufheben gebunden" }
entries[90614] = { ["name"] = "Windspiel der Kaldorei", ["text"] = "Wirken in 2 sek. 15\nDieses Windspiel besteht aus mehreren reichverzierten Bronzeröhren verschiedener Länge, die durch eine rankenförmige Bronzehalterung verbunden sind. Das Artefakt ist magisch und die Glocken erklingen von allein, selbst wenn kein Wind geht.\nWindspiel der Kaldorei\nWird beim Aufheben gebunden\nSpielzeug\nBenutzen: Haltet das Windspiel in die Brise, um das Wetter zu überprüfen. (1 Min Abklingzeit)" }
entries[90615] = { ["name"] = "Fourth and Goal: Character Earthquake" }
entries[90616] = { ["name"] = "Königin Azsharas Morgenmantel", ["text"] = "Wirken in 2 sek. 15\nDass Azshara die Schönste aller Nachtelfen war, wird praktisch als Fakt betrachtet. Unglücklicherweise scheint ihr eigenes Auge für Schönheit genauso getrübt gewesen zu sein wie das ihrer hochgeborenen Untertanen – zumindest den schreienden Farben dieses Gewandes nach zu urteilen.\n\n\"Es gab jemals nur die eine, und es wird jemals nur die eine geben... eine Azshara.\"\nKönigin Azsharas Morgenmantel\nAccountgebunden\nBrust Stoff\n258 Rüstung\n+27 Ausdauer\n+41 Intelligenz\nErhöht Eure Tempowertung um + 23.\nHaltbarkeit 165 / 165\n51\n\"Die Gerüchte über den schlechten Modegeschmack der Hochgeborenen scheinen der Wahrheit zu entsprechen.\"" }
entries[90617] = { ["name"] = "Gefiederter Raptorenarm", ["text"] = "Wirken in 2 sek. 5\nUnter den Mitgliedern der Forscherliga gibt es einige, die glauben, dass Vögel von Dinosauriern wie diesem Raptor abstammen. Die Federn deuten auf das fehlende Verbindungsglied zwischen den zwei Arten hin. Andererseits könnte es auch nur eine weitere der seltsamen Kreaturen sein, die Azeroth heimsuchen.\nGefiederter Raptorenarm\nWird beim Aufheben gebunden" }
entries[90618] = { ["name"] = "Bösartiger urtümlicher Fisch", ["text"] = "Wirken in 2 sek. 5\nDer skelettierte Fisch wird von schweren Knochenplatten geschützt und seine Kiefer sind mit hunderten nadelartiger Zähne bestückt. Einige glauben, dass einstmals Ozeane alle Kontinente Azeroths bedeckten, weswegen es möglich ist, im tiefsten Binnenland Fischfossilien zu finden.\nBösartiger urtümlicher Fisch\nWird beim Aufheben gebunden" }
entries[90619] = { ["name"] = "Fossiler Raptor", ["text"] = "Wirken in 2 sek. 15\nAls ihr damit fertig wart, dieses Skelett zusammenzusetzen, wurde es von einer gespenstischen Magie wieder zum Leben erweckt.\nFossiler Raptor\nWird beim Aufheben gebunden\nReittier\n40\nBenötigt Geübtes Reiten\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren fossilen Raptor oder gibt ihn wieder frei." }
