entries[90728] = { ["name"] = "Grauer Kerzenstummel", ["text"] = "Wirken in 2 sek. 5\nNeunundzwanzig Kerzen wurden aufgestellt, um den Schreckenslord Azagrim zu beschwören. Achtundzwanzig Orcs wurden von Azagrim getötet, bevor es Häuptling Hargal schließlich gelang, ihn zu vernichten.\nGrauer Kerzenstummel\nWird beim Aufheben gebunden" }
entries[90730] = { ["name"] = "Rostiges Steakmesser", ["text"] = "Wirken in 2 sek. 5\nDieses Messer wurde von Hargals Nebenfrau Narim in einem Eifersuchtsanfall zum Einsatz gebracht. Die rostige Klinge ist noch immer mit dem Blut des toten Häuptlings verkrustet.\nRostiges Steakmesser\nWird beim Aufheben gebunden" }
entries[90732] = { ["name"] = "Szepter von Nekros Schädelberster", ["text"] = "Wirken in 2 sek. 5\nDas klingenbewehrte Szepter des finsteren Hexenmeisters Nekros Schädelberster wurde von ihm oft als Waffe verwendet.\nSzepter von Nekros Schädelberster\nWird beim Aufheben gebunden" }
