entries[90831] = { ["name"] = "Teuflische Peitsche", ["text"] = "Wirken in 2 sek. 5\nDie Hexenmeister gewannen unter den Orcs mit Gul'dans Aufstieg an die Macht an Bedeutung. Diese Peitsche eines Sukkubus ist aus dem Leder veschiedener Kreaturen geflochten - einige davon wahrscheinlich Humanoide.\nTeuflische Peitsche\nWird beim Aufheben gebunden" }
entries[90832] = { ["name"] = "Glasierte Lehmkachel", ["text"] = "Wirken in 2 sek. 5\nEinstmals müssen viele dieser Kacheln die Wände oder den Boden einer Festung oder eines Empfangssaals auf Draenor geziert haben. Auf diesem Stück ist ein Landstrich dargestellt, der dem heutigen Nagrand sehr ähnelt, auf einem Feld aus gelber und grüner Glasur weiden Herdentiere. Der Rand ist mit einem schwarz-braunen Schachbrettmuster verziert.\nGlasierte Lehmkachel\nWird beim Aufheben gebunden" }
entries[90833] = { ["name"] = "Trinkschädel", ["text"] = "Wirken in 2 sek. 5\nDieses Gefäß sieht gefährlich aus. Durch einen Designfehler sickert sein Inhalt jedoch durch die Augenhöhlen aus. Duuuurst...\nTrinkschädel\nWird beim Aufheben gebunden" }
entries[90836] = { ["name"] = "See Quest Invis 10" }
entries[90842] = { ["name"] = "Gedankenfiederer", ["text"] = "Sofort\nErhöht Euer Tempo 20 Sek. lang um 510 ." }
entries[90843] = { ["name"] = "Kopfputz des ersten Schamanen", ["text"] = "Wirken in 2 sek. 15\nDer Ursprung des Schamanismus bei den Orcs bleibt ein Mysterium. So weit geschichtliche Aufzeichnungen der Orcs auch zurückreichen, wurden stets Schamanen in ihnen erwähnt. Dieser simple Kopfputz ist unfassbar alt. Weder der Name seines Erschaffers noch der des ursprünglichen Trägers werden jemals ans Tageslicht gebracht werden.\nKopfputz des ersten Schamanen\nAccountgebunden\nKopf Kette\n720 Rüstung\n+39 Beweglichkeit\n+21 Ausdauer\nErhöht Eure Trefferwertung um + 22.\nErhöht Eure kritische Trefferwertung um + 22.\n\nRoter Sockel\nBlauer Sockel\nGelber Sockel\nSockelbonus: + 6 Ausdauer\n\nHaltbarkeit 100 / 100\n61\nBenutzen: Gestattet es Euch, weit in die Ferne zu blicken. (1 Min Abklingzeit)" }
entries[90845] = { ["name"] = "See Quest Invis 11" }
entries[90846] = { ["name"] = "Flammenschock", ["text"] = "40 Meter Reichweite\nSofort\nVerursacht 6337 bis 6662 Feuerschaden sowie zusätzlich 8 Sek. lang alle 1 Sek. 2437 bis 2561 Feuerschaden." }
