entries[90994] = { ["name"] = "Tunnel", ["text"] = "40 Meter Reichweite\nWirken in 1 sek.\nGräbt sich unter dem Zaubernden in die Erde, wodurch er bis Abbruch lang verschwindet." }
entries[90996] = { ["name"] = "Crescendo des Leidens", ["text"] = "Sofort\nErhöht die Zaubermacht 10 Sek. lang um 606 ." }
entries[90997] = { ["name"] = "Bartaxt aus Niffelvar", ["text"] = "Wirken in 2 sek. 15\nViele von den Vrykul gefertigte Äxte haben einen ungewöhnlichen Stil: der Klingenbart streckt sich sehr weit über das Maß des Axtkopfes hinaus. Durch diese Bauweise, die sowohl für Werkzeuge als auch Waffen vewendet wird, erhöht sich die Schnittfläche, während das Gewicht minimiert wird. Einige zwergische Äxte weisen eine ähnliche Konstruktionsweise auf.\nBartaxt aus Niffelvar\nAccountgebunden\nEinhändig Axt\n540 - 1,004 Schaden Tempo 2.60\n(296.92 Schaden pro Sekunde)\n+36 Beweglichkeit\n+87 Ausdauer\nErhöht Eure Trefferwertung um + 24.\nErhöht Eure kritische Trefferwertung um + 37.\nHaltbarkeit 105 / 105\n71" }
entries[90998] = { ["name"] = "Gesang der Trauer", ["text"] = "Wenn Eure Zauber einem Ziel Schaden zufügen, das über weniger als 35% Gesundheit verfügt, wird Eure Zaubermacht 10 Sek. lang um 606 erhöht. Nachdem der Effekt endet, kann er 10 Sek. lang nicht erneut ausgelöst werden.\n(20s Abklingzeit)" }
entries[90999] = { ["name"] = "Werfen", ["text"] = "35 Meter Reichweite\nWirken in 1.5 sek.\nWirft Eure Waffe und fügt dem Ziel 200% Waffenschaden zu." }
