entries[91023] = { ["name"] = "Schwächen aufspüren", ["text"] = "Eure Fähigkeiten 'Hinterhalt', 'Erdrosseln' und 'Fieser Trick' offenbaren eine Verteidigungsschwachstelle eines Gegners, wodurch sämtliche Eurer Angriffe 10 Sek. lang 100% seiner Rüstung umgehen. Gegen Spielercharaktere wird weniger Rüstung umgangen." }
