entries[91077] = { ["name"] = "Wilder Sprung", ["text"] = "5 - 30 Meter Reichweite\nSofort\nDer wilde Spuk springt sein Ziel an, wobei das Angriffstempo des Spuks 5 Sek. lang um 50% erhöht wird." }
