entries[91080] = { ["name"] = "Item - Proc Wandering DoT", ["text"] = "Eure Schadenszauber gewähren eine Chance, dass Euer Ziel von einem rachsüchtigen Irrwisch geplagt wird, der alle 3 Sek. 542 Schaden verursacht. Zudem besteht jedes Mal, wenn der rachsüchtige irrwisch Schaden verursacht, eine Chance von 10%, dass sich der Effekt auf einen zufälligen nahen Gegner ausbreitet.\n(Procchance: 10%, 1.667Min. Abklingzeit)" }
entries[91082] = { ["name"] = "Jujuraserei", ["text"] = "100 Meter Reichweite\nSofort\nErhöht 10 Min. lang Euer Bewegungstempo um 15%. Diese Magie wirkt nur in Winterquell." }
entries[91084] = { ["name"] = "Dornenhalskette", ["text"] = "Wirken in 2 sek. 5\nDas Tragen dieser Halskette kann nur schmerzhaft sein. Sie besteht aus einer Reihe gewundener Bronzeranken, deren Dornen unglücklicherweise nach innen gerichtet sind. Möglicherweise gehörte das Schmuckstück zur Ausstattung eines Runenwirkers - oder der Juwelier war einfach nicht praktisch veranlagt.\nDornenhalskette\nWird beim Aufheben gebunden" }
entries[91085] = { ["name"] = "Goblinische Hosentaschenbombe platzieren", ["text"] = "10 Meter Reichweite\nWirken in 3 sek.\nPlatziert eine goblinische Hosentaschenbombe an einem der vorgegebenen Orte im Hügelland." }
entries[91088] = { ["name"] = "Fleisch verzehren", ["text"] = "Nahkampfreichweite\nSofort\nEntzieht dem Ziel 20% seiner maximalen Gesundheit und gewährt einen Teil der entzogenen Gesundheit dem Zaubernden." }
entries[91089] = { ["name"] = "Protodrachenskelett", ["text"] = "Wirken in 2 sek. 5\nProtodrachen sind die primitiven Vorfahren der heutigen Drachen. Dem Mythos zufolge schufen die Titanen die Aspekte aus Galakrond, einem massiven Protodrachen, dessen Knochen noch immer in der Drachenöde zu finden sind. Protodrachen sind im allgemeinen wild und zeigen keine Spuren der großen Intelligenz und Weisheit, welche die echten Drachen charakterisiert.\nProtodrachenskelett\nWird beim Aufheben gebunden" }
entries[91090] = { ["name"] = "Klaue", ["text"] = "Nahkampfreichweite\nSofort\nGreift einen Gegner mit Klauen an und verursacht Schaden." }
